16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Single source of truth for the fixed city-to-region mapping (Sydney->NSW, Melbourne->VIC,
22	 * Brisbane->QLD). Consumed by presentation (an owner's {@code locality}) and by validation (an
23	 * owner's postcode range), so both layers agree on which region a city belongs to.
24	 */
25	public final class Region {
26	
27	    /** Locality reported for a city that has no known region. */
28	    public static final String UNKNOWN = "UNKNOWN";
29	
30	    /** Fixed city-to-region lookup. */
31	    private static final Map<String, String> CITY_REGION = Map.of(
32	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    /** Region -> inclusive 4-digit postcode range {low, high}. */
35	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
36	        "NSW", new int[] {2000, 2099},
37	        "VIC", new int[] {3000, 3099},
38	        "QLD", new int[] {4000, 4099});
39	
40	    private Region() {
41	    }
42	
43	    /**
44	     * The canonical region for {@code city}, or {@code null} when the city has no known region.
45	     */
46	    public static String forCity(String city) {
47	        return CITY_REGION.get(city);
48	    }
49	
50	    /**
51	     * The canonical region whose range contains the given 4-digit {@code postcode}, or {@code null}
52	     * when the postcode is absent, not a number, or falls in no known range.
53	     */
54	    public static String forPostcode(String postcode) {
55	        if (postcode == null) {
56	            return null;
57	        }
58	        int value;
59	        try {
60	            value = Integer.parseInt(postcode.trim());
61	        } catch (NumberFormatException e) {
62	            return null;
63	        }
64	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
65	            int[] range = entry.getValue();
66	            if (value >= range[0] && value <= range[1]) {
67	                return entry.getKey();
68	            }
69	        }
70	        return null;
71	    }
72	
73	    /**
74	     * The inclusive 4-digit postcode range {@code {low, high}} for {@code region}, or {@code null}
75	     * when the region has no defined range. Returns a fresh array so callers cannot mutate the table.
76	     */
77	    public static int[] postcodeRange(String region) {
78	        int[] range = REGION_POSTCODES.get(region);
79	        return range == null ? null : new int[] {range[0], range[1]};
80	    }
81	
82	    /**
83	     * The canonical region for {@code city}, or {@link #UNKNOWN} when the city has no known region.
84	     */
85	    public static String localityForCity(String city) {
86	        String region = forCity(city);
87	        return region == null ? UNKNOWN : region;
88	    }
89	
90	    /**
91	     * The canonical region derived from the given 4-digit {@code postcode} (see
92	     * {@link #forPostcode(String)}), or {@link #UNKNOWN} when the postcode is absent or falls in no
93	     * known range. This is the {@code <REGION>} component of an owner's {@code customerCode}.
94	     */
95	    public static String regionForPostcode(String postcode) {
96	        String region = forPostcode(postcode);
97	        return region == null ? UNKNOWN : region;
98	    }
99	
100	    /**
101	     * The {@code <REGION>} component of a {@code customerCode} formatted {@code '<REGION>-<HASH8>'}
102	     * — the text before the first {@code '-'} — or {@link #UNKNOWN} when {@code customerCode} is
103	     * {@code null}, blank, or carries no separator.
104	     */
105	    public static String regionOfCustomerCode(String customerCode) {
106	        if (customerCode == null || customerCode.isBlank()) {
107	            return UNKNOWN;
108	        }
109	        int dash = customerCode.indexOf('-');
110	        return dash <= 0 ? UNKNOWN : customerCode.substring(0, dash);
111	    }
112	
113	    /**
114	     * The canonical region derived by preferring the {@code postcode} range, and only falling back
115	     * to the city-to-region table when the postcode is absent or in no known range. Returns
116	     * {@link #UNKNOWN} when neither the postcode nor the city yields a region.
117	     */
118	    public static String locality(String city, String postcode) {
119	        String region = forPostcode(postcode);
120	        if (region == null) {
121	            region = forCity(city);
122	        }
123	        return region == null ? UNKNOWN : region;
124	    }
125	}
