245	    @Override
246	    @Transactional(readOnly = true)
247	    public Collection<Vet> findVets() throws DataAccessException {
248	        return vetRepository.findAll();
249	    }
250	
251	    /**
252	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
253	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
254	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
255	     * a known region (see {@link Region}), the postcode must fall within that region's range
256	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
257	     * postcode.
258	     *
259	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
260	     */
261	    private void assertPostcodeValid(Owner owner) {
262	        String postcode = owner.getPostcode();
263	        if (postcode == null) {
264	            return;
265	        }
266	        String region = Region.forCity(owner.getCity());
267	        int[] range = region == null ? null : Region.postcodeRange(region);
268	        if (range == null) {
269	            return;
270	        }
271	        int value = Integer.parseInt(postcode);
272	        if (value < range[0] || value > range[1]) {
273	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
274	        }
275	    }
276	
277	    @Override
278	    @Transactional
279	    public void saveOwner(Owner owner) throws DataAccessException {
280	        assertPostcodeValid(owner);
281	        if (owner.getTelephone() != null) {
282	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
283	        }
284	        if (owner.getEmail() != null) {
285	            owner.setEmail(normalizeEmail(owner.getEmail()));
286	        }
287	        if (owner.getAddress() != null) {
288	            owner.setAddress(normalizeAddress(owner.getAddress()));
289	        }
290	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
291	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
292	        if (owner.getCustomerCode() == null) {
293	            owner.setCustomerCode(generateCustomerCode(owner));
294	        }
295	        boolean creating = owner.isNew();
296	        if (creating) {
297	            owner.setNamesakeCount(countNamesakes(owner));
298	            assertDailyCapacity(owner);
299	            assertCityCapacity(owner);
300	        }
301	        List<Owner> household = findHouseholdMembers(owner);
302	        assignHousehold(owner, household);
303	        assertIdentityUnique(owner);
304	        ownerRepository.save(owner);
305	        populateHouseholdSize(owner);
306	        if (creating) {
307	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
308	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
309	                owner.getMembershipLevel());
310	        }
311	    }
312	
313	    /**
314	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
315	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
316	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
317	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
318	     * {@link #saveOwner(Owner)} before this runs.
319	     */
320	    private String generateCustomerCode(Owner owner) {
321	        String region = Region.regionForPostcode(owner.getPostcode());
322	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
323	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
324	        String hash8 = sha256UpperHex(telephone + lastName, 8);
325	        return region + "-" + hash8;
326	    }
327	
328	    /**
329	     * The first {@code chars} upper-case hex characters of the SHA-256 digest of {@code value}'s
330	     * UTF-8 bytes.
331	     */
332	    private static String sha256UpperHex(String value, int chars) {
333	        try {
334	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
335	            byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
336	            StringBuilder sb = new StringBuilder(hash.length * 2);
337	            for (byte b : hash) {
338	                sb.append(String.format("%02X", b));
339	            }
340	            return sb.substring(0, chars);
341	        } catch (NoSuchAlgorithmException e) {
342	            throw new IllegalStateException("SHA-256 not available", e);
343	        }
344	    }
345	
346	    /** Maximum number of owners permitted in a single city. */
347	    private static final long CITY_OWNER_LIMIT = 50L;
348	
349	    /**
350	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
351	     * more owners, so no city can grow beyond the capacity limit.
352	     *
353	     * @throws CityOwnerLimitException if the owner's city is already at capacity
354	     */
355	    private void assertCityCapacity(Owner owner) {
356	        if (owner.getCity() == null) {
357	            return;
358	        }
359	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
360	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
361	        }
362	    }
363	
364	    /**
365	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
366	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
367	     */
368	    private static LocalDate rollToBusinessDay(LocalDate date) {
369	        switch (date.getDayOfWeek()) {
370	            case SATURDAY:
371	                return date.plusDays(2);
372	            case SUNDAY:
373	                return date.plusDays(1);
374	            default:
375	                return date;
376	        }
377	    }
378	
379	    /** Maximum number of owners permitted to be registered on a single day. */
380	    private static final long DAILY_OWNER_LIMIT = 100L;
381	
382	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
383	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
384	
385	    /**
386	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
387	     * today, reusing the same daily accumulation as the per-day create limit ({@link
388	     * #assertDailyCapacity}).
389	     */
390	    @Override
391	    @Transactional(readOnly = true)
392	    public boolean isBulkSignupWarningActive() throws DataAccessException {
393	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
394	    }
395	
396	    /**
397	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
398	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
399	     * many owners can be created on any single day.
400	     *
401	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
402	     */
403	    private void assertDailyCapacity(Owner owner) {
404	        LocalDate date = owner.getRegistrationDate();
405	        if (date == null) {
406	            return;
407	        }
408	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
409	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
410	        }
411	    }
412	
413	    private long countOwnersRegisteredOn(LocalDate date) {
414	        return ownerRepository.findAll().stream()
415	                .filter(existing -> date.equals(existing.getRegistrationDate()))
416	                .count();
417	    }
418	
419	    private long countOwnersInCity(String city) {
420	        String normalized = normalizeHouseholdValue(city);
421	        return ownerRepository.findAll().stream()
422	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
423	                .count();
424	    }
425	
426	    /**
427	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
428	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
429	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
430	     * that already existed before this create.
431	     */
432	    private int countNamesakes(Owner owner) {
433	        String firstName = normalizeHouseholdValue(owner.getFirstName());
434	        String lastName = normalizeHouseholdValue(owner.getLastName());
435	        int count = 0;
436	        for (Owner existing : ownerRepository.findAll()) {
437	            if (!existing.getId().equals(owner.getId())
438	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
439	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
440	                count++;
441	            }
442	        }
443	        return count;
444	    }
445	
446	    private static String normalizeEmail(String email) {
447	        return email == null ? null : email.toLowerCase(Locale.ROOT);
448	    }
449	
450	    /** Common street-type abbreviations expanded during address normalization. */
451	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
452	        "ST", "STREET",
453	        "RD", "ROAD",
454	        "AVE", "AVENUE");
455	
456	    /**
457	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
458	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
459	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
460	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
461	     * form.
462	     */
463	    private static String normalizeAddress(String address) {
464	        if (address == null) {
465	            return null;
466	        }
467	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
468	        if (collapsed.isEmpty()) {
469	            return "";
470	        }
471	        String[] tokens = collapsed.split(" ");
472	        StringBuilder sb = new StringBuilder(collapsed.length());
473	        for (int i = 0; i < tokens.length; i++) {
474	            if (i > 0) {
475	                sb.append(' ');
476	            }
477	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
478	        }
479	        return sb.toString();
480	    }
481	
482	    private static String normalizeTelephone(String telephone) {
483	        return telephone == null ? null : E164Telephone.toE164(telephone);
484	    }
485	
486	    /**
487	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
488	     * that of another owner. This single check consolidates the former separate telephone, email and
489	     * household duplicate rules: because the normalized telephone is part of the key, two members of
490	     * the same household (same {@code householdId}) with different telephones have different keys and
491	     * are both allowed — only an exact full-key match is a duplicate.
492	     *
493	     * @throws DuplicateIdentityException if another owner already has the same identity key
494	     */
495	    private void assertIdentityUnique(Owner owner) {
496	        String identityKey = owner.getIdentityKey();
497	        for (Owner existing : ownerRepository.findAll()) {
498	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
499	                throw new DuplicateIdentityException(identityKey);
500	            }
501	        }
502	    }
503	
504	    /**
505	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
506	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
507	     * members of the household it would join. Returns an empty list for an update to an existing
508	     * owner or when either household value is blank, so household rules only apply to genuine new
509	     * members.
510	     */
511	    private List<Owner> findHouseholdMembers(Owner owner) {
512	        if (!owner.isNew()) {
513	            return List.of();
514	        }
515	        String lastName = normalizeHouseholdValue(owner.getLastName());
516	        String address = normalizeHouseholdAddress(owner.getAddress());
517	        if (lastName.isEmpty() || address.isEmpty()) {
518	            return List.of();
519	        }
520	        List<Owner> household = new ArrayList<>();
521	        for (Owner existing : ownerRepository.findAll()) {
522	            if (!existing.getId().equals(owner.getId())
523	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
524	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
525	                household.add(existing);
526	            }
527	        }
528	        return household;
529	    }
530	
531	    /**
532	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
533	     * owner and every matching existing member that lacks one are given the same stable
534	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
535	     * is empty.
536	     */
537	    private void assignHousehold(Owner owner, List<Owner> household) {
538	        if (household.isEmpty()) {
539	            return;
540	        }
541	        String householdId = resolveHouseholdId(owner, household);
542	        owner.setHouseholdId(householdId);
543	        for (Owner existing : household) {
544	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
545	                existing.setHouseholdId(householdId);
546	                ownerRepository.save(existing);
547	            }
548	        }
549	    }
550	
551	    /**
552	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
553	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
554	     * reaching into the data store. A {@code null} owner or one without a household id is left at
555	     * size 0.
556	     */
557	    private void populateHouseholdSize(Owner owner) {
558	        if (owner == null) {
559	            return;
560	        }
561	        String householdId = owner.getHouseholdId();
562	        if (householdId == null || householdId.isBlank()) {
563	            owner.setHouseholdSize(0);
564	            return;
565	        }
566	        int count = 0;
567	        for (Owner existing : ownerRepository.findAll()) {
568	            if (householdId.equals(existing.getHouseholdId())) {
569	                count++;
570	            }
571	        }
572	        owner.setHouseholdSize(count);
573	    }
574	
575	    /**
576	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
577	     * store, so a list/page of owners is counted without a per-owner query.
578	     *
579	     * @see #populateHouseholdSize(Owner)
580	     */
581	    private void populateHouseholdSizes(Collection<Owner> owners) {
582	        if (owners.isEmpty()) {
583	            return;
584	        }
585	        Map<String, Integer> sizes = new HashMap<>();
586	        for (Owner existing : ownerRepository.findAll()) {
587	            String householdId = existing.getHouseholdId();
588	            if (householdId != null && !householdId.isBlank()) {
589	                sizes.merge(householdId, 1, Integer::sum);
590	            }
591	        }
592	        for (Owner owner : owners) {
593	            String householdId = owner.getHouseholdId();
594	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
595	        }
596	    }
597	
598	    /**
599	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
600	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
601	     * joining {@code owner}'s normalized lastName and address.
602	     */
603	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
604	        for (Owner existing : household) {
605	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
606	                return existing.getHouseholdId();
607	            }
608	        }
609	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
610	            normalizeHouseholdAddress(owner.getAddress()));
611	    }
612	
613	    /**
614	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
615	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
616	     * household deterministically share the same identifier.
617	     */
618	    private static String generateHouseholdId(String lastName, String address) {
619	        try {
620	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
621	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
622	            StringBuilder sb = new StringBuilder();
623	            for (int i = 0; i < 6; i++) {
624	                sb.append(String.format("%02X", hash[i]));
625	            }
626	            return "HH-" + sb;
627	        } catch (NoSuchAlgorithmException e) {
628	            throw new IllegalStateException("SHA-256 not available", e);
629	        }
630	    }
631	
632	    /**
633	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
634	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
635	     */
636	    private static String normalizeHouseholdValue(String value) {
637	        if (value == null) {
638	            return "";
639	        }
640	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
641	    }
642	
643	    /**
644	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
645	     * form (never {@code null}), so duplicate detection and the shared household id compare
646	     * addresses using the same normalized representation that is stored and returned.
647	     */
648	    private static String normalizeHouseholdAddress(String address) {
649	        String normalized = normalizeAddress(address);
650	        return normalized == null ? "" : normalized;
651	    }
652	
653	    @Override
654	    @Transactional(readOnly = true)
655	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
656	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
657	        populateHouseholdSizes(owners);
658	        return owners;
659	    }
660	
661	    @Override
662	    @Transactional(readOnly = true)
663	    public Collection<Visit> findVisitsByPetId(int petId) {
664	        return visitRepository.findByPetId(petId);
665	    }
666	
667	    @Override
668	    @Transactional(readOnly = true)
669	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
670	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
671	    }
672	
673	    private <T> T findEntityById(Supplier<T> supplier) {
674	        try {
675	            return supplier.get();
676	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
677	            // Just ignore not found exceptions for Jdbc/Jpa realization
678	            return null;
679	        }
680	    }
681	
682	}
